'use strict';
function gameCameraTarget(){const width=worldWidth();return width<=W?(width-W)/2:clamp(player.x-W*.42,0,width-W)}
function fitGameViewport(){if(screen!=='play')return;const bounds=document.querySelector('.playfield').getBoundingClientRect();if(bounds.width<1||bounds.height<1)return;const width=Math.max(1,Math.round(H*bounds.width/bounds.height));if(canvas.width!==width||canvas.height!==H){W=width;canvas.width=width;canvas.height=H;ctx.imageSmoothingEnabled=false}camera=gameCameraTarget()}
function drawViewportGround(){const left=Math.min(0,camera-2),right=Math.max(worldWidth(),camera+W+2);for(const [x,width]of [[left,-left],[worldWidth(),right-worldWidth()]]){if(width<=0)continue;ctx.fillStyle=getCliffPattern(true);ctx.fillRect(x,420,width,H-420);grassEdge(x,420,width)}}
async function toggleGameFullscreen(){try{if(document.fullscreenElement||document.webkitFullscreenElement){const exit=document.exitFullscreen||document.webkitExitFullscreen;if(exit)await exit.call(document)}else{const request=document.documentElement.requestFullscreen||document.documentElement.webkitRequestFullscreen;if(!request){toast('เบราว์เซอร์นี้ไม่รองรับปุ่มเต็มจอ · พื้นที่เล่นยังเต็มหน้าต่างอยู่');return}await request.call(document.documentElement)}if(!$('modal').hidden)closeModal();fitGameViewport()}catch{toast('เปิดเต็มหน้าจอไม่สำเร็จ ลองกดปุ่มเต็มจออีกครั้ง')}}
const fullscreenButton=document.createElement('button');fullscreenButton.id='gameFullscreenBtn';fullscreenButton.textContent='⛶ เต็มจอ';fullscreenButton.setAttribute('aria-label','เปิดเต็มหน้าจอ');fullscreenButton.onclick=toggleGameFullscreen;document.querySelector('.playfield').append(fullscreenButton);
function syncFullscreenButton(){const full=!!(document.fullscreenElement||document.webkitFullscreenElement);fullscreenButton.textContent=full?'⛶ ย่อจอ':'⛶ เต็มจอ';fullscreenButton.setAttribute('aria-label',full?'ออกจากเต็มหน้าจอ':'เปิดเต็มหน้าจอ');requestAnimationFrame(fitGameViewport)}
new ResizeObserver(()=>fitGameViewport()).observe(document.querySelector('.playfield'));window.addEventListener('resize',fitGameViewport);window.visualViewport?.addEventListener('resize',fitGameViewport);document.addEventListener('fullscreenchange',syncFullscreenButton);document.addEventListener('webkitfullscreenchange',syncFullscreenButton);
